// Expo config plugin: turns on React Native's `enableAccessibilityOrder` feature flag on iOS and
// Android. The flag is off in stable React Native builds, and without it the native views ignore
// `experimental_accessibilityOrder`, so `AccessibilityOrder` and `screenReaderOrder` do nothing.
//
// ios/ and android/ are generated by `expo prebuild` (and gitignored), so the change lives here.
// After changing this plugin, run `npx expo prebuild` and rebuild the app.
//
// React Native applies its release-level flags once, when the app starts it. This plugin replaces
// them right afterwards (before React Native reads any flag) with the same stable flags plus this
// one. The canary and experimental release levels already turn the flag on.
const fs = require("fs");
const path = require("path");
const {
  IOSConfig,
  createRunOncePlugin,
  withAppDelegate,
  withDangerousMod,
  withMainApplication,
  withXcodeProject,
} = require("expo/config-plugins");

const IOS_FILES = ["AccessibilityOrderFlag.h", "AccessibilityOrderFlag.mm"];
const IOS_CALL = "AccessibilityOrderFlag.enable()";
const IOS_FACTORY_LINE = /^(\s*)let factory = ExpoReactNativeFactory\(delegate: delegate\)\s*$/m;

const ANDROID_MARKER = "// Reading order for screen readers: see plugins/accessibility-order.";
const ANDROID_LOAD_LINE = /^(\s*)(loadReactNative\(this\)|DefaultNewArchitectureEntryPoint\.load\(\))\s*$/m;
const ANDROID_IMPORTS = [
  "com.facebook.react.common.ReleaseLevel",
  "com.facebook.react.defaults.DefaultNewArchitectureEntryPoint",
  "com.facebook.react.internal.featureflags.ReactNativeFeatureFlags",
  "com.facebook.react.internal.featureflags.ReactNativeNewArchitectureFeatureFlagsDefaults",
];

// --- iOS ----------------------------------------------------------------------------------------

/** Copies the Objective-C++ helper into ios/<project>/ and exposes it to Swift. */
function withIosHelperFiles(config) {
  return withDangerousMod(config, [
    "ios",
    (config) => {
      const sourceRoot = IOSConfig.Paths.getSourceRoot(config.modRequest.projectRoot);
      for (const file of IOS_FILES) {
        fs.copyFileSync(path.join(__dirname, file), path.join(sourceRoot, file));
      }

      const bridgingHeader = fs
        .readdirSync(sourceRoot)
        .find((file) => file.endsWith("-Bridging-Header.h"));
      if (!bridgingHeader) {
        throw new Error(`accessibility-order: no *-Bridging-Header.h in ${sourceRoot}`);
      }
      const headerPath = path.join(sourceRoot, bridgingHeader);
      const header = fs.readFileSync(headerPath, "utf8");
      const importLine = '#import "AccessibilityOrderFlag.h"';
      if (!header.includes(importLine)) {
        fs.writeFileSync(headerPath, `${header.trimEnd()}\n${importLine}\n`);
      }
      return config;
    },
  ]);
}

/** Compiles the .mm file into the app target. Skips it if it is already in the project. */
function withIosHelperInProject(config) {
  return withXcodeProject(config, (config) => {
    const projectName = IOSConfig.XcodeUtils.getProjectName(config.modRequest.projectRoot);
    const project = config.modResults;
    IOSConfig.XcodeUtils.addBuildSourceFileToGroup({
      filepath: path.join(projectName, "AccessibilityOrderFlag.mm"),
      groupName: projectName,
      project,
    });
    compileHelperAsObjcpp(project);
    return config;
  });
}

/**
 * Makes sure Xcode compiles the .mm file. The `xcode` package has no file type for .mm (so it
 * writes "unknown"), and a later prebuild can list the file under Resources instead of Sources.
 */
function compileHelperAsObjcpp(project) {
  const objects = project.hash.project.objects;
  const entries = (section) => Object.entries(objects[section] ?? {}).filter(([key]) => !key.endsWith("_comment"));
  const isHelper = (name) => typeof name === "string" && name.replace(/"/g, "") === "AccessibilityOrderFlag.mm";

  const refIds = entries("PBXFileReference")
    .filter(([, ref]) => isHelper(ref.name) || isHelper(path.basename(String(ref.path ?? ""))))
    .map(([id, ref]) => {
      ref.lastKnownFileType = "sourcecode.cpp.objcpp";
      delete ref.explicitFileType;
      delete ref.fileEncoding;
      return id;
    });
  const buildIds = entries("PBXBuildFile")
    .filter(([, file]) => refIds.includes(file.fileRef))
    .map(([id]) => id);
  if (buildIds.length === 0) throw new Error("accessibility-order: AccessibilityOrderFlag.mm isn't in the Xcode project");

  for (const [, phase] of entries("PBXResourcesBuildPhase")) {
    phase.files = phase.files.filter((file) => !buildIds.includes(file.value));
  }
  const sources = project.pbxSourcesBuildPhaseObj(project.getFirstTarget().uuid);
  const listed = sources.files.find((file) => buildIds.includes(file.value));
  if (listed) listed.comment = "AccessibilityOrderFlag.mm in Sources";
  else sources.files.push({ value: buildIds[0], comment: "AccessibilityOrderFlag.mm in Sources" });
  objects.PBXBuildFile[`${buildIds[0]}_comment`] = "AccessibilityOrderFlag.mm in Sources";
}

/** Calls the helper right after the React Native factory is created. */
function withIosFlagCall(config) {
  return withAppDelegate(config, (config) => {
    if (config.modResults.language !== "swift") {
      throw new Error("accessibility-order: expected a Swift AppDelegate");
    }
    config.modResults.contents = addIosFlagCall(config.modResults.contents);
    return config;
  });
}

function addIosFlagCall(contents) {
  if (contents.includes(IOS_CALL)) return contents;
  if (!IOS_FACTORY_LINE.test(contents)) {
    throw new Error(
      "accessibility-order: couldn't find `let factory = ExpoReactNativeFactory(delegate: delegate)` in AppDelegate.swift",
    );
  }
  return contents.replace(
    IOS_FACTORY_LINE,
    (line, indent) =>
      `${line}\n${indent}// Reading order for screen readers: see plugins/accessibility-order.\n${indent}${IOS_CALL}`,
  );
}

// --- Android ------------------------------------------------------------------------------------

/** Replaces the stable flags with the same flags plus reading order, right after they're loaded. */
function withAndroidFlag(config) {
  return withMainApplication(config, (config) => {
    if (config.modResults.language !== "kt") {
      throw new Error("accessibility-order: expected a Kotlin MainApplication");
    }
    config.modResults.contents = addAndroidFlag(config.modResults.contents);
    return config;
  });
}

function addAndroidFlag(contents) {
  if (contents.includes(ANDROID_MARKER)) return contents;
  if (!ANDROID_LOAD_LINE.test(contents)) {
    throw new Error(
      "accessibility-order: couldn't find `loadReactNative(this)` or `DefaultNewArchitectureEntryPoint.load()` in MainApplication.kt",
    );
  }
  let next = contents.replace(ANDROID_LOAD_LINE, (line, indent) =>
    [
      line,
      `${indent}${ANDROID_MARKER}`,
      `${indent}// Canary and experimental release levels already turn the flag on.`,
      `${indent}if (DefaultNewArchitectureEntryPoint.releaseLevel == ReleaseLevel.STABLE) {`,
      `${indent}  ReactNativeFeatureFlags.dangerouslyForceOverride(`,
      `${indent}    object : ReactNativeNewArchitectureFeatureFlagsDefaults() {`,
      `${indent}      override fun enableAccessibilityOrder(): Boolean = true`,
      `${indent}    },`,
      `${indent}  )`,
      `${indent}}`,
    ].join("\n"),
  );
  const missing = ANDROID_IMPORTS.filter((name) => !new RegExp(`^import ${name.replace(/\./g, "\\.")}$`, "m").test(next));
  if (missing.length > 0) {
    // Add them in front of the first import, or after the package line if there are none.
    const lines = missing.map((name) => `import ${name}\n`).join("");
    next = /^import /m.test(next)
      ? next.replace(/^import /m, `${lines}import `)
      : next.replace(/^(package [^\n]+\n)/m, `$1\n${lines}`);
  }
  return next;
}

// --- Plugin -------------------------------------------------------------------------------------

function withAccessibilityOrder(config) {
  config = withIosHelperFiles(config);
  config = withIosHelperInProject(config);
  config = withIosFlagCall(config);
  config = withAndroidFlag(config);
  return config;
}

module.exports = createRunOncePlugin(withAccessibilityOrder, "accessibility-order", "1.0.0");
module.exports.addIosFlagCall = addIosFlagCall;
module.exports.addAndroidFlag = addAndroidFlag;
